import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"53、【漸】 艮下巽上","description":"周易尚氏學 - 53、【漸】 艮下巽上","frontmatter":{"title":"53、【漸】 艮下巽上","description":"周易尚氏學 - 53、【漸】 艮下巽上"},"headers":[],"relativePath":"classics/shangshi/058.md","filePath":"classics/shangshi/058.md"}'),s={name:"classics/shangshi/058.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_53、【漸】-艮下巽上" tabindex="-1">53、【漸】 艮下巽上 <a class="header-anchor" href="#_53、【漸】-艮下巽上" aria-label="Permalink to “53、【漸】 艮下巽上”">​</a></h1><p>上下卦皆陰承陽。陰承陽即婦從夫。故曰日漸。漸進也。次也。言陰次於是。宜進而承陽也。巽為婦。艮止於下。有女歸之象。二五應。故利貞而吉。</p><p>彖曰。漸之進也。女歸吉也。進得位。往有功也。進以正。可以正邦也。其位。剛得中也。止而巽。動不窮也。</p><p>五得位故有功。艮為邦。故曰正邦。</p><p>象曰。山上有木。漸。君子以居賢德善俗。</p><p>居積也。居賢德。即積賢德也。坎為積。艮為賢。巽為風俗。有賢德故以善俗。居賢德善俗。皆非猝然可能之事。皆漸義也。</p><p>初六。鴻漸於乾。小子厲。有言。無咎。</p><p>鴻大雁也。艮為鴻。周公時訓。以雁北鄉當屯卦。是以坎為北。互艮為雁。故易林師之萃雲。鴻雁啞啞。以水為家。以萃互艮為鴻也。需之遁雲。去如飛鴻。亦以遁下艮為鴻。千水涯也。二至四坎水。初在坎下。故曰鴻漸於乾。艮少故為小子。有言者爭訟。震為言。艮為反震。敗言。故曰有言。左傳雲。敗言為讒是也。有言故厲。然初為士。潛伏在下。亦無咎也。</p><h3 id="象曰。小子之厲。義無咎也。" tabindex="-1">象曰。小子之厲。義無咎也。 <a class="header-anchor" href="#象曰。小子之厲。義無咎也。" aria-label="Permalink to “象曰。小子之厲。義無咎也。”">​</a></h3><p>初勿用。故義無咎。</p><p>六二。鴻漸於磐，飲食衎衎，吉。</p><p>盤大石也。三艮為石。故漸於盤。二坎體。坎為飲食。衎衎。和樂也。二當位得中應五。故象吉如是。</p><h3 id="象曰。飲食衎衎。不素飽也。" tabindex="-1">象曰。飲食衎衎。不素飽也。 <a class="header-anchor" href="#象曰。飲食衎衎。不素飽也。" aria-label="Permalink to “象曰。飲食衎衎。不素飽也。”">​</a></h3><p>坎中實為飽。應在五。巽為白。故曰素飽。素飽猶素餐。不素飽。言得之以道也。</p><p>九三。鴻漸於陸。夫徵不復。婦孕不育。兇。利禦寇。</p><p>馬雲。山上高平曰陸。艮為夫。在上。故不復。易林復之剝雲。夫亡從軍。抱膝獨宿。以剝艮為夫也。孕。妊娠也。育生也。震為孕。左傳昭元年。武王邑姜。方震太叔是也。三震覆。故不育。郭璞洞林否之小過雲。婦女胎反見華益。否三互巽。故知為婦女。二四互艮。世變良。艮為反震。是胎反也。胎亦孕也。義即本此也。巽為寇。三下擁群陰。而艮為守禦。為堅。寇在外。守禦在內。使外寇不人。故利也。舊解皆以坎為寇。豈知坎之為寇。以其隱伏。巽亦為伏。故易亦以巽為寇。且以坎為寇。坎寇已在內矣。如何能御之。虞翻以坎為寇。謂自上御下。自上御下。其利在上。於三何與。一象失傳。使經義顛倒錯亂。至於如此。真可喂也。</p><h3 id="象曰。夫徵不復。離群五也。婦孕不育。失其道出。利用御冠。順相保也。" tabindex="-1">象曰。夫徵不復。離群五也。婦孕不育。失其道出。利用御冠。順相保也。 <a class="header-anchor" href="#象曰。夫徵不復。離群五也。婦孕不育。失其道出。利用御冠。順相保也。" aria-label="Permalink to “象曰。夫徵不復。離群五也。婦孕不育。失其道出。利用御冠。順相保也。”">​</a></h3><p>坤為眾為醜，醜眾也。詩小雅。執訊獲五是也。高附離也。群醜謂下二陰。言三陽繫戀於下二陰。故不復也。諸家訓離為去。與下順相保之義不合。非也。艮為道。坎為失。故失道不育。下二陰順三陽。以為保守。故曰順相保。</p><p>六四。鴻漸於木。或得其桷。無咎。</p><p>巽為鴻。九家逸象巽為鸛。鸛鴻皆水鳥。故亦為鴻。周公時訓以鴻雁來當巽卦。是以巽為鴻。故易林中孚之同人雲。鴻飛遵陸。以同人互巽為鴻。又大畜之兌雲。鴻盜我襦。逃于山隅。兌互巽為盜為鴻。舊以離為鴻非也。巽為木為桷。說文椽方曰桷。得桷言安也。四當位承陽。故無咎。</p><h3 id="象曰。或得其桷。順以巽也。言順承五上二陽。" tabindex="-1">象曰。或得其桷。順以巽也。言順承五上二陽。 <a class="header-anchor" href="#象曰。或得其桷。順以巽也。言順承五上二陽。" aria-label="Permalink to “象曰。或得其桷。順以巽也。言順承五上二陽。”">​</a></h3><p>九五。鴻漸於陵。婦三歲不孕。終莫之勝。吉。</p><p>巽為高。五應在二。二艮體。五居艮上。故漸於陵。巽為婦。震為孕。震伏。下敝漏。故不孕。又五應在二。為三所阻。不能應二。故三歲不孕。坎為三歲。言其久。然五與二為正應。三豈能終阻之。故終勝三。得所願而吉也。莫之勝。言三不能勝五也。</p><h3 id="象曰。終莫之勝吉。得所願也。" tabindex="-1">象曰。終莫之勝吉。得所願也。 <a class="header-anchor" href="#象曰。終莫之勝吉。得所願也。" aria-label="Permalink to “象曰。終莫之勝吉。得所願也。”">​</a></h3><p>五終能應二。故得所願。舊解皆從虞氏以成既濟定為說。強命初上變。非。</p><p>上九。鴻漸於陸。其羽可用為儀。吉。</p><p>在卦上。與三同。故仍漸於陸。巽為羽。儀飾也。其羽可用為儀者。巽為高為白。言上居高明之地。羽毛鮮潔。故可用以為儀。賁一切也。巽羽之象。易林隨之小畜雲。奮翅鼓翼。以小畜上巽為翼。又頤之兌六翮長翼。亦以兌互類為翼。</p><h3 id="象曰。其羽可用為儀吉。不可亂也。" tabindex="-1">象曰。其羽可用為儀吉。不可亂也。 <a class="header-anchor" href="#象曰。其羽可用為儀吉。不可亂也。" aria-label="Permalink to “象曰。其羽可用為儀吉。不可亂也。”">​</a></h3><p>儀型萬方。秩然不紊。故不可亂。</p>',29)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
